export function lookupTefasFund(code: string): { code: string; name: string; category?: string; tefasStatus?: string } | null {
  const upper = code.trim().toUpperCase();
  if (TEFAS_FUNDS_DICTIONARY[upper]) {
    return {
      code: upper,
      name: TEFAS_FUNDS_DICTIONARY[upper].name,
      category: TEFAS_FUNDS_DICTIONARY[upper].category,
      tefasStatus: TEFAS_FUNDS_DICTIONARY[upper].tefasStatus
    };
  }
  return null;
}

export function searchTefasFunds(query: string): Array<{ code: string; name: string; category?: string; tefasStatus?: string }> {
  const q = query.trim().toUpperCase();
  if (!q) return [];
  const startsWithCode: Array<{ code: string; name: string; category?: string; tefasStatus?: string }> = [];
  const containsCode: Array<{ code: string; name: string; category?: string; tefasStatus?: string }> = [];
  const containsName: Array<{ code: string; name: string; category?: string; tefasStatus?: string }> = [];

  for (const [code, item] of Object.entries(TEFAS_FUNDS_DICTIONARY)) {
    if (code === q) {
      startsWithCode.unshift({ code, name: item.name, category: item.category, tefasStatus: item.tefasStatus });
    } else if (code.startsWith(q)) {
      startsWithCode.push({ code, name: item.name, category: item.category, tefasStatus: item.tefasStatus });
    } else if (code.includes(q)) {
      containsCode.push({ code, name: item.name, category: item.category, tefasStatus: item.tefasStatus });
    } else if (item.name.toUpperCase().includes(q)) {
      containsName.push({ code, name: item.name, category: item.category, tefasStatus: item.tefasStatus });
    }
  }

  return [...startsWithCode, ...containsCode, ...containsName].slice(0, 20);
}
